// O(n²): all pairs i < j — n(n − 1)/2 comparisons
int CountEqualPairs(int[] a) {
    int c = 0;
    for (int i = 0; i < a.Length; i++)
        for (int j = i + 1; j < a.Length; j++)
            if (a[i] == a[j]) c++;
    return c;
}

int CountMatches(int[] a, int[] b) {
    int c = 0;
    foreach (int x in a)
        foreach (int y in b)
            if (x == y) c++;
    foreach (int y in b)
        if (y == 0) c++;
    return c;
}

