public int LargestRectangleArea(int[] h) {
    var stack = new Stack<int>(); // indices, heights increasing
    int best = 0;
    for (int i = 0; i <= h.Length; i++) {
        int cur = i == h.Length ? 0 : h[i];             // sentinel of height 0
