// region labels on a flat grid; region and queue have length w·h and are reused
int Label(bool[] open, int w, int h, int[] region, int[] queue) {
    Array.Fill(region, -1);
    int count = 0, head, tail = 0;
    void Push(int j) {
        if (open[j] && region[j] == -1) { region[j] = count; queue[tail++] = j; }
    }
    for (int s = 0; s < w * h; s++) {
        if (!open[s] || region[s] != -1) continue;
        head = tail = 0;
        Push(s);                             // a new region numbered count
        while (head < tail) {
            int i = queue[head++], x = i % w;
            if (x > 0) Push(i - 1);
            if (x < w - 1) Push(i + 1);
            if (i >= w) Push(i - w);
            if (i < w * (h - 1)) Push(i + w);
        }
        count++;
    }
    return count;
}

